const response = xml2Json(pm.response.text());
const accounts = response.accounts.account;

const expectedCustomerId = Number(
    pm.collectionVariables.get("customerId")
);


pm.test("Status Code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Account list is not empty", function () {
    pm.expect(accounts).to.be.an("array").that.is.not.empty;
});


pm.test("All accounts belong to the customer", function () {
    accounts.forEach(account => {
        pm.expect(Number(account.customerId))
            .to.equal(expectedCustomerId);
    });
});

pm.test("Invalid Customer ID returns 400", function () {
    pm.response.to.have.status(400);
});

